fn torneo(valores: &Vec<int>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // We have three distinct indices i, j, k.
    // The goal is to pick two distinct indices among them, say x, y,
    // so that valores[x] >= valores[y],
    // and the third index z satisfies valores[y] >= valores[z].

    // Let's extract the values for convenience:
    let vi = valores[i];
    let vj = valores[j];
    let vk = valores[k];

    // We want to find a pair (x,y) from {i,j,k} with x!=y
    // ordered non-increasingly by values: valores[x] >= valores[y],
    // and the leftover index z such that valores[y] >= valores[z].

    // There are only 3 indices, so we can check all triple orderings.
    //
    // Steps:
    // 1) Sort the triple values along with their indices.
    // 2) Return the top two indices with descending order.
    //
    // But note the postcondition requires the returned result to have
    // valores[res.0] >= valores[res.1] >= valores[x], where x is third index.
    //
    // This is ensured by simply sorting the triple.

    // Create a small array of tuples: (index, value)
    let mut triple = [(i, vi), (j, vj), (k, vk)];

    // Sort descending by value
    triple.sort_by(|a, b| b.1.cmp(&a.1));

    // Return the top two indices (in descending value order)
    // triple[0].0 != triple[1].0 guaranteed since indices distinct

    (triple[0].0, triple[1].0)
}